(7138548, 1093282, 114285, '<td valign="top">yeah i thought this was pretty good!</td>', 'yeah i thought this was pretty good!', '2013-12-04 00:40:45.000000', NULL, 0),
(7138552, 1093287, 93565, '<td valign="top">Much better layering than many of the images above it. The cloud placement above the pelican is great.<br/> <br/>Sad to see this as low as it is.</td>', 'Much better layering than many of the images above it. The cloud placement above the pelican is great. Sad to see this as low as it is.', '2013-12-04 00:46:48.000000', NULL, 0),
(7138553, 1093368, 93565, '<td valign="top">Pushed too hard in processing.</td>', 'Pushed too hard in processing.', '2013-12-04 00:47:33.000000', NULL, 0),
(7138554, 1093471, 93565, '<td valign="top">I like the coolness (har har).<br/> <br/>Really enjoy the trees arched over the river, and I enjoy even more how the river pulls me through all the great layers of depth here. Well done.</td>', 'I like the coolness (har har). Really enjoy the trees arched over the river, and I enjoy even more how the river pulls me through all the great layers of depth here. Well done.', '2013-12-04 00:49:47.000000', NULL, 0),
(7138556, 1093466, 93565, '<td valign="top">I think the composition works well here. The initially cluttered foreground might impede some, but the waterway leads us nicely through the rest. Interesting sepia type processing.</td>', 'I think the composition works well here. The initially cluttered foreground might impede some, but the waterway leads us nicely through the rest. Interesting sepia type processing.', '2013-12-04 00:52:05.000000', NULL, 0),
(7138561, 1093412, 93565, '<td valign="top">This is interesting. I appreciate the antithesis of normally romanticized landscapes, and this is very nice. The horizon is one of those frustratingly "never looks right" types, so I understand the feeling of tilt here.</td>', 'This is interesting. I appreciate the antithesis of normally romanticized landscapes, and this is very nice. The horizon is one of those frustratingly "never looks right" types, so I understand the feeling of tilt here.', '2013-12-04 00:55:46.000000', NULL, 0),
(7138564, 1093181, 93565, '<td valign="top">I''d actually appreciate this more if you pushed the hell out of everything in it like a "traditional" landscape. I feel like you''d bring the point home more effectively. Romanticize this "gorgeous" landscape by all means!</td>', 'I''d actually appreciate this more if you pushed the hell out of everything in it like a "traditional" landscape. I feel like you''d bring the point home more effectively. Romanticize this "gorgeous" landscape by all means!', '2013-12-04 00:57:47.000000', NULL, 0),
(7138566, 1093371, 68504, '<td valign="top">beautiful. great foreground, great progression to the vanishing point.</td>', 'beautiful. great foreground, great progression to the vanishing point.', '2013-12-04 01:00:26.000000', NULL, 0),
(7138570, 1093242, 68504, '<td valign="top">piece de resistance is your foreground group of pylons with the grasses contemplating the Ozmandian follies of civilization. well shown. lots going on but your colours and tones contain it.</td>', 'piece de resistance is your foreground group of pylons with the grasses contemplating the Ozmandian follies of civilization. well shown. lots going on but your colours and tones contain it.', '2013-12-04 01:06:29.000000', NULL, 0),
(7138571, 1093339, 68504, '<td valign="top">well constructed/seen.</td>', 'well constructed/seen.', '2013-12-04 01:08:06.000000', NULL, 0),
(7138575, 1093220, 68504, '<td valign="top">just before dusk I come with my brush.</td>', 'just before dusk I come with my brush.', '2013-12-04 01:13:04.000000', NULL, 0),
(7138579, 1093226, 58667, '<td valign="top">Thank you for the comments... The layering is the foreground trees, then the tall trees poking through and then the clouds.</td>', 'Thank you for the comments... The layering is the foreground trees, then the tall trees poking through and then the clouds.', '2013-12-04 01:21:50.000000', NULL, 0),
(7138589, 1093228, 104230, '<td valign="top">WTG, sweetie. Beautifully processed, lovely lines. Congrats on the ribbon.</td>', 'WTG, sweetie. Beautifully processed, lovely lines. Congrats on the ribbon.', '2013-12-04 01:35:03.000000', NULL, 0);
