(7138640, 1093421, 6519, '<td valign="top">That cat is such a lovely surprise.... a very unexpected bonus.</td>', 'That cat is such a lovely surprise.... a very unexpected bonus.', '2013-12-04 02:40:20.000000', NULL, 0),
